insert into public.translations (locale, key, value) values
  ('pt-BR', 'mods.intro', $json$"Mods acrescentam coisas ao JayV, como os mods de um jogo: motores de LLM, recursos, agentes, skills e o que mais o app aprender a receber. Você os instala pela página de cada mod no site, com a sua conta, e o app sincroniza na hora; aqui você liga, desliga e desinstala cada um, e as mudanças valem quando você salva. Os essenciais, que são os recursos do app, ficam sempre instalados e ligados."$json$::jsonb),
  ('en', 'mods.intro', $json$"Mods add to JayV, like mods in a game: LLM engines, features, agents, skills and whatever the app learns to take next. You install them from each mod's page on the site, signed in, and the app syncs right away; here you turn each one on or off and uninstall it, and the changes apply when you save. The essential ones, the features of the app, always stay installed and on."$json$::jsonb),
  ('es', 'mods.intro', $json$"Los mods añaden cosas a JayV, como los mods de un juego: motores de LLM, funciones, agentes, skills y lo que la app aprenda a recibir después. Los instalas desde la página de cada mod en el sitio, con tu cuenta, y la app sincroniza al momento; aquí activas, desactivas y desinstalas cada uno, y los cambios valen al guardar. Los esenciales, que son las funciones de la app, siempre se quedan instalados y activados."$json$::jsonb),
  ('zh-CN', 'mods.intro', $json$"模组为 JayV 增加内容，就像游戏里的模组：LLM 引擎、功能、代理、技能，以及应用以后能接收的其他内容。你在网站上每个模组的页面中（登录状态下）安装它们，应用会立即同步；在这里你可以开启、关闭和卸载每个模组，保存后更改生效。必需模组即应用的功能，始终保持安装并开启。"$json$::jsonb),
  ('hi', 'mods.intro', $json$"मॉड JayV में चीज़ें जोड़ते हैं, जैसे किसी गेम के मॉड: LLM इंजन, सुविधाएँ, एजेंट, स्किल और ऐप आगे जो भी लेना सीखे। आप उन्हें साइट पर हर मॉड के पेज से, अपने खाते से, इंस्टॉल करते हैं और ऐप तुरंत सिंक करता है; यहाँ आप हर एक को चालू, बंद और अनइंस्टॉल करते हैं, और बदलाव सहेजने पर लागू होते हैं। ज़रूरी मॉड, यानी ऐप की सुविधाएँ, हमेशा इंस्टॉल और चालू रहते हैं।"$json$::jsonb),
  ('ar', 'mods.intro', $json$"تضيف الإضافات أشياء إلى JayV، مثل إضافات الألعاب: محركات LLM والميزات والوكلاء والمهارات وكل ما يتعلّم التطبيق استقباله لاحقًا. تثبّتها من صفحة كل إضافة على الموقع بعد تسجيل الدخول، ويزامن التطبيق فورًا؛ وهنا تفعّل كل إضافة أو تعطّلها أو تلغي تثبيتها، وتسري التغييرات عند الحفظ. أما الإضافات الأساسية، وهي ميزات التطبيق، فتبقى مثبّتة ومفعّلة دائمًا."$json$::jsonb),
  ('fr', 'mods.intro', $json$"Les mods ajoutent des choses à JayV, comme les mods d’un jeu : moteurs LLM, fonctionnalités, agents, skills et tout ce que l’app saura recevoir ensuite. Vous les installez depuis la page de chaque mod sur le site, connecté, et l’app se synchronise tout de suite ; ici, vous activez, désactivez et désinstallez chacun, et les changements s’appliquent à l’enregistrement. Les essentiels, c’est-à-dire les fonctionnalités de l’app, restent toujours installés et activés."$json$::jsonb),
  ('ru', 'mods.intro', $json$"Моды добавляют в JayV новое, как моды в игре: движки LLM, функции, агентов, скиллы и всё, что приложение научится принимать. Вы устанавливаете их со страницы каждого мода на сайте, войдя в аккаунт, и приложение сразу синхронизируется; здесь вы включаете, выключаете и удаляете каждый, а изменения вступают в силу после сохранения. Обязательные моды — функции приложения — всегда остаются установленными и включёнными."$json$::jsonb),
  ('ja', 'mods.intro', $json$"Mod はゲームの Mod のように JayV に機能を追加します。LLM エンジン、機能、エージェント、スキル、そして今後アプリが受け取れるようになるもの。インストールはサインインした状態でサイトの各 Mod のページから行い、アプリはすぐに同期します。ここでは各 Mod のオン／オフとアンインストールができ、変更は保存したときに反映されます。必須の Mod（アプリの機能）は常にインストール済みでオンのままです。"$json$::jsonb),
  ('de', 'mods.intro', $json$"Mods erweitern JayV wie Mods in einem Spiel: LLM-Engines, Funktionen, Agenten, Skills und alles, was die App künftig aufnehmen kann. Sie installieren sie über die Seite jedes Mods auf der Website, angemeldet, und die App synchronisiert sofort; hier schalten Sie jeden ein oder aus und deinstallieren ihn, und Änderungen gelten beim Speichern. Die unverzichtbaren Mods – die Funktionen der App – bleiben immer installiert und eingeschaltet."$json$::jsonb),
  ('pt-BR', 'mods.installedEmpty.site', $json$"Nenhum mod instalado. Instale um pela página dele no site."$json$::jsonb),
  ('en', 'mods.installedEmpty.site', $json$"No mod installed. Install one from its page on the site."$json$::jsonb),
  ('es', 'mods.installedEmpty.site', $json$"Ningún mod instalado. Instala uno desde su página en el sitio."$json$::jsonb),
  ('zh-CN', 'mods.installedEmpty.site', $json$"没有已安装的模组。请在网站上该模组的页面中安装。"$json$::jsonb),
  ('hi', 'mods.installedEmpty.site', $json$"कोई मॉड इंस्टॉल नहीं है। साइट पर किसी मॉड के पेज से एक इंस्टॉल करें।"$json$::jsonb),
  ('ar', 'mods.installedEmpty.site', $json$"لا توجد إضافات مثبّتة. ثبّت إضافة من صفحتها على الموقع."$json$::jsonb),
  ('fr', 'mods.installedEmpty.site', $json$"Aucun mod installé. Installez-en un depuis sa page sur le site."$json$::jsonb),
  ('ru', 'mods.installedEmpty.site', $json$"Нет установленных модов. Установите мод с его страницы на сайте."$json$::jsonb),
  ('ja', 'mods.installedEmpty.site', $json$"インストール済みの Mod はありません。サイトの Mod のページからインストールしてください。"$json$::jsonb),
  ('de', 'mods.installedEmpty.site', $json$"Kein Mod installiert. Installieren Sie einen über seine Seite auf der Website."$json$::jsonb),
  ('pt-BR', 'mods.uninstall.undo', $json$"Desfazer"$json$::jsonb),
  ('en', 'mods.uninstall.undo', $json$"Undo"$json$::jsonb),
