  ('pt-BR', 'mods.fromSite.installed', $json$"{name} foi instalado pelo site."$json$::jsonb),
  ('en', 'mods.fromSite.installed', $json$"{name} was installed from the site."$json$::jsonb),
  ('es', 'mods.fromSite.installed', $json$"{name} se instaló desde el sitio."$json$::jsonb),
  ('zh-CN', 'mods.fromSite.installed', $json$"{name} 已从网站安装。"$json$::jsonb),
  ('hi', 'mods.fromSite.installed', $json$"{name} साइट से इंस्टॉल हो गया।"$json$::jsonb),
  ('ar', 'mods.fromSite.installed', $json$"تم تثبيت {name} من الموقع."$json$::jsonb),
  ('fr', 'mods.fromSite.installed', $json$"{name} a été installé depuis le site."$json$::jsonb),
  ('ru', 'mods.fromSite.installed', $json$"{name} установлен с сайта."$json$::jsonb),
  ('ja', 'mods.fromSite.installed', $json$"{name} をサイトからインストールしました。"$json$::jsonb),
  ('de', 'mods.fromSite.installed', $json$"{name} wurde über die Website installiert."$json$::jsonb),
  ('pt-BR', 'mods.fromSite.otherEnvironment', $json$"{name} foi instalado em outro ambiente: troque para ele para usar o mod."$json$::jsonb),
  ('en', 'mods.fromSite.otherEnvironment', $json$"{name} was installed in another environment: switch to it to use the mod."$json$::jsonb),
  ('es', 'mods.fromSite.otherEnvironment', $json$"{name} se instaló en otro entorno: cambia a él para usar el mod."$json$::jsonb),
  ('zh-CN', 'mods.fromSite.otherEnvironment', $json$"{name} 安装在另一个环境中：切换到该环境即可使用这个模组。"$json$::jsonb),
  ('hi', 'mods.fromSite.otherEnvironment', $json$"{name} किसी दूसरे परिवेश में इंस्टॉल हुआ है: मॉड इस्तेमाल करने के लिए उस परिवेश पर जाएँ।"$json$::jsonb),
  ('ar', 'mods.fromSite.otherEnvironment', $json$"تم تثبيت {name} في بيئة أخرى: انتقل إليها لاستخدام الإضافة."$json$::jsonb),
  ('fr', 'mods.fromSite.otherEnvironment', $json$"{name} a été installé dans un autre environnement : passez-y pour utiliser le mod."$json$::jsonb),
  ('ru', 'mods.fromSite.otherEnvironment', $json$"{name} установлен в другой среде: переключитесь на неё, чтобы пользоваться модом."$json$::jsonb),
  ('ja', 'mods.fromSite.otherEnvironment', $json$"{name} は別の環境にインストールされました。使うにはその環境に切り替えてください。"$json$::jsonb),
  ('de', 'mods.fromSite.otherEnvironment', $json$"{name} wurde in einer anderen Umgebung installiert: Wechseln Sie dorthin, um den Mod zu nutzen."$json$::jsonb),
  ('pt-BR', 'guidance.installAgentModFix', $json$"Instale o mod do agente que você usa pela página dele no site — Claude Code, Codex, Ollama e os outros — ou ligue-o em Configuração › Mods e salve."$json$::jsonb),
  ('en', 'guidance.installAgentModFix', $json$"Install the mod of the agent you use from its page on the site — Claude Code, Codex, Ollama and the others — or turn it on in Settings › Mods and save."$json$::jsonb),
  ('es', 'guidance.installAgentModFix', $json$"Instala el mod del agente que usas desde su página en el sitio — Claude Code, Codex, Ollama y los demás — o actívalo en Configuración › Mods y guarda."$json$::jsonb),
  ('zh-CN', 'guidance.installAgentModFix', $json$"在网站上你所用代理的模组页面中安装它（Claude Code、Codex、Ollama 等），或在“设置 › 模组”中开启它，然后保存。"$json$::jsonb),
  ('hi', 'guidance.installAgentModFix', $json$"जिस एजेंट का आप इस्तेमाल करते हैं उसका मॉड साइट पर उसके पेज से इंस्टॉल करें — Claude Code, Codex, Ollama और बाकी — या सेटिंग्स › मॉड में उसे चालू करें और सहेजें।"$json$::jsonb),
  ('ar', 'guidance.installAgentModFix', $json$"ثبّت إضافة الوكيل الذي تستخدمه من صفحتها على الموقع — Claude Code وCodex وOllama وغيرها — أو فعّلها في الإعدادات › الإضافات ثم احفظ."$json$::jsonb),
  ('fr', 'guidance.installAgentModFix', $json$"Installez le mod de l’agent que vous utilisez depuis sa page sur le site — Claude Code, Codex, Ollama et les autres — ou activez-le dans Configuration › Mods, puis enregistrez."$json$::jsonb),
  ('ru', 'guidance.installAgentModFix', $json$"Установите мод агента, которым вы пользуетесь, с его страницы на сайте — Claude Code, Codex, Ollama и другие — или включите его в Настройки › Моды и сохраните."$json$::jsonb),
  ('ja', 'guidance.installAgentModFix', $json$"使っているエージェントの Mod をサイトのそのページからインストールするか（Claude Code、Codex、Ollama など）、設定 › Mod でオンにして保存してください。"$json$::jsonb),
  ('de', 'guidance.installAgentModFix', $json$"Installieren Sie den Mod des Agenten, den Sie nutzen, über seine Seite auf der Website – Claude Code, Codex, Ollama und die anderen – oder schalten Sie ihn unter Einstellungen › Mods ein und speichern Sie."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.installFromSite.title', $json$"Os mods se instalam pelo site"$json$::jsonb),
  ('en', 'whatsNew.item.installFromSite.title', $json$"Mods install from the site"$json$::jsonb),
  ('es', 'whatsNew.item.installFromSite.title', $json$"Los mods se instalan desde el sitio"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.installFromSite.title', $json$"模组改为从网站安装"$json$::jsonb),
  ('hi', 'whatsNew.item.installFromSite.title', $json$"मॉड अब साइट से इंस्टॉल होते हैं"$json$::jsonb),
  ('ar', 'whatsNew.item.installFromSite.title', $json$"تُثبَّت الإضافات من الموقع"$json$::jsonb),
  ('fr', 'whatsNew.item.installFromSite.title', $json$"Les mods s’installent depuis le site"$json$::jsonb),
  ('ru', 'whatsNew.item.installFromSite.title', $json$"Моды устанавливаются с сайта"$json$::jsonb),
  ('ja', 'whatsNew.item.installFromSite.title', $json$"Mod はサイトからインストール"$json$::jsonb),
  ('de', 'whatsNew.item.installFromSite.title', $json$"Mods werden über die Website installiert"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.installFromSite.detail', $json$"Configuração › Mods não lista mais o catálogo. Abra a página do mod no site, com a sua conta, e clique em Instalar no JayV: o site o grava na sua conta e o app sincroniza na hora, e o mod aparece em Instalados. Um mod desinstalado fica na lista, com Desfazer, até você salvar."$json$::jsonb),
  ('en', 'whatsNew.item.installFromSite.detail', $json$"Settings › Mods no longer lists the catalog. Open the mod's page on the site, signed in, and click Install in JayV: the site saves it in your account and the app syncs right away, so the mod shows up in Installed. An uninstall waits in the list, with Undo, until you save."$json$::jsonb),
  ('es', 'whatsNew.item.installFromSite.detail', $json$"Configuración › Mods ya no lista el catálogo. Abre la página del mod en el sitio, con tu cuenta, y haz clic en Instalar en JayV: el sitio lo guarda en tu cuenta y la app sincroniza al momento, y el mod aparece en Instalados. Un mod desinstalado queda en la lista, con Deshacer, hasta que guardes."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.installFromSite.detail', $json$"“设置 › 模组”不再列出目录。登录后在网站上打开模组的页面，点击“在 JayV 中安装”：网站会把它保存到你的账户，应用立即同步，模组随即出现在“已安装”中。卸载的模组会留在列表中并显示“撤销”，直到你保存。"$json$::jsonb),
  ('hi', 'whatsNew.item.installFromSite.detail', $json$"सेटिंग्स › मॉड अब कैटलॉग की सूची नहीं दिखाता। साइट पर मॉड का पेज अपने खाते से खोलें और JayV में इंस्टॉल करें पर क्लिक करें: साइट उसे आपके खाते में सहेजती है और ऐप तुरंत सिंक करता है, और मॉड इंस्टॉल किए गए में दिखता है। अनइंस्टॉल किया गया मॉड सहेजने तक पूर्ववत करें के साथ सूची में रहता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.installFromSite.detail', $json$"لم تعد الإعدادات › الإضافات تعرض الفهرس. افتح صفحة الإضافة على الموقع بعد تسجيل الدخول وانقر «التثبيت في JayV»: يحفظها الموقع في حسابك ويزامن التطبيق فورًا، فتظهر الإضافة في «المثبّتة». تبقى الإضافة التي ألغيت تثبيتها في القائمة مع «تراجع» حتى تحفظ."$json$::jsonb),
  ('fr', 'whatsNew.item.installFromSite.detail', $json$"Configuration › Mods ne liste plus le catalogue. Ouvrez la page du mod sur le site, connecté, et cliquez sur Installer dans JayV : le site l’enregistre dans votre compte et l’app se synchronise tout de suite, et le mod apparaît dans Installés. Un mod désinstallé reste dans la liste, avec Annuler, jusqu’à l’enregistrement."$json$::jsonb),
  ('ru', 'whatsNew.item.installFromSite.detail', $json$"В Настройки › Моды больше нет списка каталога. Откройте страницу мода на сайте, войдя в аккаунт, и нажмите «Установить в JayV»: сайт сохранит его в вашем аккаунте, приложение сразу синхронизируется, и мод появится во вкладке «Установленные». Удалённый мод остаётся в списке с кнопкой «Отменить», пока вы не сохраните."$json$::jsonb),
  ('ja', 'whatsNew.item.installFromSite.detail', $json$"設定 › Mod にカタログの一覧は表示されなくなりました。サインインした状態でサイトの Mod のページを開き、「JayV にインストール」をクリックします。サイトがアカウントに保存してアプリがすぐに同期し、Mod が「インストール済み」に表示されます。アンインストールした Mod は、保存するまで「元に戻す」付きで一覧に残ります。"$json$::jsonb),
  ('de', 'whatsNew.item.installFromSite.detail', $json$"Einstellungen › Mods listet den Katalog nicht mehr. Öffnen Sie angemeldet die Seite des Mods auf der Website und klicken Sie auf „In JayV installieren“: Die Website speichert ihn in Ihrem Konto, die App synchronisiert sofort, und der Mod erscheint unter „Installiert“. Ein deinstallierter Mod bleibt mit „Rückgängig“ in der Liste, bis Sie speichern."$json$::jsonb),
  ('pt-BR', 'site.modPages.install.button', $json$"Instalar no JayV"$json$::jsonb),
